long long solve(const string &a, const string &b) {
    long long difference = 0, empty = 0, answer = 0;
    for (size_t i = 0; i < a.size(); i++) {
        char x = a[i], y = b[i];
        if (x == '?' && y == '?') {
            empty++;
            continue;
        }
