        if (x == '?') {
            x = y == 'R' ? 'W' : 'R';
            answer++;
        }
        if (y == '?') answer++;
        difference += x == 'R' ? 1 : -1;
    }
    // each double-? column fixes one unit of the top row imbalance with 2 replacements
    return llabs(difference) <= empty ? answer + 2 * llabs(difference) : -1;
