import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    static long solve(String a, String b) {
        long difference = 0, empty = 0, answer = 0;
        for (int i = 0; i < a.length(); i++) {
            char x = a.charAt(i), y = b.charAt(i);
            if (x == '?' && y == '?') {
                empty++;
                continue;
            }
            if (x == y) return -1; // fixed same-color column
            if (x == '?') {
                x = y == 'R' ? 'W' : 'R';
                answer++;
            }
            if (y == '?') answer++;
            difference += x == 'R' ? 1 : -1;
        }
        // each double-? column fixes one unit of the top row imbalance with 2 replacements
        return Math.abs(difference) <= empty ? answer + 2 * Math.abs(difference) : -1;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        nextInt();
        String a = next(), b = next();
        System.out.println(solve(a, b));
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func solve(a, b []byte) int64 {
	var difference, empty, answer int64
	for i := range a {
		x, y := a[i], b[i]
		if x == '?' && y == '?' {
			empty++
			continue
		}
		if x == y {
			return -1 // fixed same-color column
		}
		if x == '?' {
			if y == 'R' {
				x = 'W'
			} else {
				x = 'R'
			}
			answer++
		}
		if y == '?' {
			answer++
		}
		if x == 'R' {
			difference++
		} else {
			difference--
		}
	}
	if difference < 0 {
		difference = -difference
	}
	// each double-? column fixes one unit of the top row imbalance with 2 replacements
	if difference <= empty {
		return answer + 2*difference
	}
	return -1
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	nextInt()
	a, b := next(), next()
	fmt.Println(solve(a, b))
}
